using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using WhatsBiz.Application.Common.Interfaces;
using WhatsBiz.Infrastructure.Customers;
using WhatsBiz.Infrastructure.Identity;
using WhatsBiz.Infrastructure.Inventory;
using WhatsBiz.Infrastructure.Persistence;
using WhatsBiz.Infrastructure.POS;
using WhatsBiz.Infrastructure.Products;
using WhatsBiz.Infrastructure.Purchases;
using WhatsBiz.Infrastructure.Suppliers;
using WhatsBiz.Infrastructure.Warehouses;
using WhatsBiz.Infrastructure.DemoRequests;
namespace WhatsBiz.Infrastructure;
public static class DependencyInjection { public static IServiceCollection AddInfrastructure(this IServiceCollection services, IConfiguration configuration) { var connectionString = configuration.GetConnectionString("DefaultConnection"); if (string.IsNullOrWhiteSpace(connectionString)) throw new InvalidOperationException("Connection string 'DefaultConnection' is missing or empty. Configure ConnectionStrings:DefaultConnection (environment variable ConnectionStrings__DefaultConnection) before starting the API."); services.AddDbContext<ApplicationDbContext>(options => options.UseSqlServer(connectionString)); services.AddIdentity<ApplicationUser, ApplicationRole>(options => { options.Password.RequiredLength = 10; options.Password.RequireDigit = true; options.Password.RequireUppercase = true; options.Password.RequireNonAlphanumeric = true; options.User.RequireUniqueEmail = true; }).AddEntityFrameworkStores<ApplicationDbContext>().AddDefaultTokenProviders(); services.AddOptions<IdentityBootstrapOptions>().Bind(configuration.GetSection(IdentityBootstrapOptions.SectionName)); services.AddOptions<JwtOptions>().Bind(configuration.GetRequiredSection(JwtOptions.SectionName)).Validate(x => !string.IsNullOrWhiteSpace(x.Issuer), "JWT issuer is required.").Validate(x => !string.IsNullOrWhiteSpace(x.Audience), "JWT audience is required.").Validate(x => x.SigningKey.Length >= 32, "JWT signing key must contain at least 32 characters.").Validate(x => x.ExpiryMinutes > 0 && x.RefreshTokenExpiryDays > 0, "JWT expiry values must be positive.").ValidateOnStart(); services.AddOptions<DemoRequestOptions>().Bind(configuration.GetSection(DemoRequestOptions.SectionName)); services.AddScoped<IDemoRequestRepository, DemoRequestRepository>(); services.AddScoped<IDemoRequestNotificationService, DemoRequestNotificationService>(); services.AddHttpClient<IDemoRequestCaptchaVerifier, DemoRequestCaptchaVerifier>(); services.AddHttpContextAccessor(); services.AddScoped<ICurrentUserService, CurrentUserService>(); services.AddScoped<IAuthenticationService, AuthenticationService>(); services.AddScoped<SqlIdempotencyExecutor>(); services.AddScoped<IProductRepository, ProductRepository>(); services.AddSingleton<IProductSpreadsheetService, ProductSpreadsheetService>(); services.AddScoped<ISupplierRepository, SupplierRepository>(); services.AddSingleton<ISupplierSpreadsheetService, SupplierSpreadsheetService>(); services.AddScoped<ICustomerRepository, CustomerRepository>(); services.AddSingleton<ICustomerSpreadsheetService, CustomerSpreadsheetService>(); services.AddScoped<IWarehouseRepository, WarehouseRepository>(); services.AddSingleton<IWarehouseSpreadsheetService, WarehouseSpreadsheetService>(); services.AddScoped<IInventoryRepository, InventoryRepository>(); services.AddScoped<IInventoryService, InventoryService>(); services.AddSingleton<IInventorySpreadsheetService, InventorySpreadsheetService>(); services.AddScoped<IPOSRepository, POSRepository>(); services.AddScoped<IPOSEngine, POSEngine>(); services.AddSingleton<IPOSDocumentService, POSDocumentService>(); services.AddScoped<IPurchaseRepository, PurchaseRepository>(); services.AddScoped<IFinanceRepository, FinanceRepository>(); services.AddScoped<IPurchaseEngine, PurchaseEngine>(); services.AddSingleton<IPurchaseSpreadsheetService, PurchaseSpreadsheetService>(); services.AddSingleton<JwtTokenGenerator>(); services.AddHostedService<IdentitySeeder>(); return services; } }
